const data = $("Extraer solicitud de reserva").all().map(item => item.json);
let participantes = data.map(item => item["Correos participantes"]);

// Si no hay participantes, error
if (!participantes || participantes.length === 0) {
  return [{
    json: {
      error: true,
      mensaje: 'Debe incluir al menos un participante en el campo "participantes".'
    }
  }];
}

// Si llega como texto separado por comas
if (!Array.isArray(participantes)) {
  participantes = typeof participantes === 'string'
    ? participantes.split(',').map(c => c.trim())
    : [];
}

// Validación de formato
const regexCorreo = /^[\w.-]+@[\w.-]+\.[A-Za-z]{2,}$/;
const validos = participantes.filter((c, i, self) => regexCorreo.test(c) && self.indexOf(c) === i);
const invalidos = participantes.filter(c => !regexCorreo.test(c));

// Si hay inválidos, error
if (invalidos.length > 0) {
  return [{
    json: {
      error: true,
      mensaje: `❌ Correos inválidos detectados: ${invalidos.join(', ')}`
    }
  }];
}

return [{
  json: {
    ...data,
    participantesValidos: validos,
    totalParticipantes: validos.length
  }
}];

