function parseHora(horaStr) {
  if (!horaStr || typeof horaStr !== 'string') return null;

  const partes = horaStr.trim().split(' ');
  if (partes.length < 2) return null;

  const [time, meridian] = partes;
  const [hoursStr, minutesStr] = time.split(':');
  if (!hoursStr || !minutesStr || !meridian) return null;

  let hours = parseInt(hoursStr, 10);
  let minutes = parseInt(minutesStr, 10);

  const meridianLower = meridian.toLowerCase();
  if (meridianLower === 'p.m.' && hours < 12) hours += 12;
  if (meridianLower === 'a.m.' && hours === 12) hours = 0;

  return hours * 60 + minutes;
}

