function horaEnMinutos(horaStr) {
  horaStr = horaStr.trim().toLowerCase();

  // Caso 1: formato con am/pm → "10:00:00 a.m."
  if (horaStr.includes("a.m.") || horaStr.includes("p.m.")) {
    const [time, meridian] = horaStr.split(" ");
    const [hStr, mStr, sStr] = time.split(":");

    let horas = parseInt(hStr, 10);
    const minutos = parseInt(mStr, 10);
    const segundos = sStr ? parseInt(sStr, 10) : 0;

    if (meridian === "p.m." && horas !== 12) {
      horas += 12;
    }
    if (meridian === "a.m." && horas === 12) {
      horas = 0;
    }

    return horas * 60 + minutos + Math.floor(segundos / 60);
  }

  // Caso 2: formato 24 horas → "10:00" o "14:00"
  const [hStr, mStr] = horaStr.split(":");
  const horas = parseInt(hStr, 10);
  const minutos = parseInt(mStr, 10);

  return horas * 60 + minutos;
}



function normalizarFecha(fechaStr) {
  fechaStr = fechaStr.trim();

  // Caso 1: formato DD/MM/YYYY → "20/12/2025"
  if (fechaStr.includes("/")) {
    const [dia, mes, anio] = fechaStr.split("/");
    return new Date(`${anio}-${mes.padStart(2,"0")}-${dia.padStart(2,"0")}`);
  }

  // Caso 2: formato YYYY-MM-DD → "2025-12-20"
  if (fechaStr.includes("-")) {
    return new Date(fechaStr);
  }

  throw new Error("Formato de fecha no reconocido: " + fechaStr);
}




function validarReserva(reservas) {
